// Formatear HTML de resumen
const d = $input.first().json;
const top = (d.top_topics || []).slice(0,5).map(t => `<li><b>${t.topic}</b>: ${t.n}</li>`).join('');
const incidents = d.incidents_reported || 0;
const color = incidents > 10 ? '#b3261e' : incidents > 3 ? '#d97706' : '#1a7f37';
const html = `
<div style="font-family:system-ui,Arial,sans-serif;max-width:640px">
  <h2 style="color:#1f4e79">Resumen diario SecBot — ${new Date().toISOString().slice(0,10)}</h2>
  <table cellpadding="8" style="border-collapse:collapse">
    <tr><td>Consultas totales</td><td><b>${d.total_queries}</b></td></tr>
    <tr><td>Resueltas sin escalar</td><td><b>${d.resolved_without_escalation}</b></td></tr>
    <tr><td>Incidentes</td><td><b style="color:${color}">${incidents}</b></td></tr>
    <tr><td>Latencia p95</td><td><b>${d.p95_latency_ms} ms</b></td></tr>
    <tr><td>Cobertura citas</td><td><b>${d.citation_coverage}%</b></td></tr>
    <tr><td>Horas ahorradas</td><td><b>${d.hours_saved}</b></td></tr>
  </table>
  <h3>Temas frecuentes</h3>
  <ul>${top}</ul>
  <p style="color:#666;font-size:12px">Enviado automáticamente por SecBot.</p>
</div>`;
return [{ json: { html, metrics: d } }];
